                    i += 1

                # Skip comments
                if i < j1 - 2 and text[i:i+1] == b'%':
                    while i < j1 - 2 and text[i:i+1] not in b'\r\n':
                        i += 1
                    while i < j1 - 2 and text[i:i+1] in b'\r\n':
                        i += 1
                    continue

                break

            if i >= j1 - 2:
                break

            # Parse value
            h_val, i, t_val = next_token(text, i)
            if t_val:
                if t_val == 'DICT':
                    obj = parse_obj(text[h_val:i])
                elif t_val == 'ARRAY':
                    obj = parse_obj(text[h_val:i])
                elif t_val == 'TRUE':
                    obj = True
                elif t_val == 'FALSE':
                    obj = False
                elif t_val == 'NAME':
                    obj = text[h_val:i].decode('ascii')
                elif t_val == 'INTEGER' or t_val == 'REAL':
                    try:
                        obj = float(text[h_val:i]) if b'.' in text[h_val:i] or b'e' in text[h_val:i].lower() else int(text[h_val:i])
                    except ValueError:
                        # If conversion fails, treat as string
                        obj = text[h_val:i]
                elif t_val == 'STRING':
                    obj = text[h_val:i]
                else:
                    obj = text[h_val:i]
                res[key] = obj
        return res

    elif t1 == 'ARRAY':
        res = []
        i = h1 + 1  # Skip the [
        while i < j1 - 1:  # Skip the ]
            # Skip whitespace and comments
            while i < j1 - 1:
                # Skip whitespace
                while i < j1 - 1 and text[i:i+1] in b' \n\r\t':
                    i += 1

                # Skip comments
                if i < j1 - 1 and text[i:i+1] == b'%':
                    while i < j1 - 1 and text[i:i+1] not in b'\r\n':
                        i += 1
                    while i < j1 - 1 and text[i:i+1] in b'\r\n':
                        i += 1
                    continue

                break

            if i >= j1 - 1:
                break

            h, i, ttt = next_token(text, i)
            if ttt:
                if ttt == 'DICT':
                    obj = parse_obj(text[h:i])
                elif ttt == 'ARRAY':
                    obj = parse_obj(text[h:i])
                elif ttt == 'TRUE':
                    obj = True
                elif ttt == 'FALSE':
                    obj = False
                elif ttt == 'NAME':
                    obj = text[h:i].decode('ascii')
                elif ttt == 'INTEGER' or ttt == 'REAL':
                    try:
                        obj = float(text[h:i]) if b'.' in text[h:i] or b'e' in text[h:i].lower() else int(text[h:i])
                    except ValueError:
                        # If conversion fails, treat as string
                        obj = text[h:i]
                elif ttt == 'STRING':
                    obj = text[h:i]
                else:
                    obj = text[h:i]
                res.append(obj)
        # Process references in array
        res = replace_ref(res)
        return res
    elif t1 == 'TRUE':
